float map(float value, float low1, float high1, float low2, float high2){
	return low2 + (value - low1) * (high2 - low2) / (high1 - low1);
}


// Triplanar mapping
vec3 BlendNormal(vec3 normal){
	vec3 blending = abs(normal);
	blending = normalize(max(blending, 0.00001));
	blending /= vec3(blending.x + blending.y + blending.z);
	return blending;
}
vec3 TriplanarMapping (sampler2D tex, vec3 normal, vec3 position) {
	vec3 normalBlend = BlendNormal(normal);
	vec3 xColor = texture(tex, position.yz).rgb;
	vec3 yColor = texture(tex, position.xz).rgb;
	vec3 zColor = texture(tex, position.xy).rgb;

  	return (xColor * normalBlend.x + yColor * normalBlend.y + zColor * normalBlend.z);
}


// Smooth noise
const mat2 smm2 = mat2(1.6,-1.2,1.2,1.6);
float Noise( in vec2 p )
{
    return 0.5*(cos(6.2831*p.x) + cos(6.2831*p.y));
}
float SmoothNoise( vec2 p )
{
    p *= 0.0013;

    float s = 1.0;
	float t0 = 0.0;
	for( int i=0; i<1; i++ )
	{
        t0 += s*Noise( p );
		s *= 0.5 + 0.1*t0;
        p = 0.97*smm2*p + (t0-0.5)*0.2;
	}
	return t0;
}


