#define FOV 1.0

#define SKY_COLOR vec3(1.)/255.

int NUM_BOUNCES =1;
#define MAX_STEPS 512
#define SURFACE_DIST 1e-4
#define MAX_DIST 2010.0
#define NUM_AO_STEPS 8.

#define MAT_RAILS 0
#define MAT_TUBE 1

const float RAIL_WIDTH = 1.0;
const float RAIL_HEIGHT = 0.6;
int glob = 0;

float RailAngle(in float z){
    return SmoothNoise(vec2(5.,4.)*z)*4.-2.;
}
vec3 RailPath(in vec3 p, vec2 offset){
    float roll = RailAngle(p.z);

    pTwist(offset.xy, roll);

    vec3 q = p + vec3(offset.xy, 0.0);

    q += vec3(sin(iTime), SmoothNoise(vec2(8.,9.)*p.z)*2.-1., sin(iTime));

    return q;
}

Hit Rails(in vec3 p){
    vec3 q = vec3(-p.x, -p.y, p.z);

    // Rails
    vec3 leftD = RailPath(q, vec2(-0.5*RAIL_WIDTH, RAIL_HEIGHT));
    vec3 rightD = RailPath(q, vec2(0.5*RAIL_WIDTH, RAIL_HEIGHT));
    vec3 bottomD = RailPath(q, vec2(0.0, 0.0));

    const float railRadius = 0.07;
    float rightRail = length(leftD.xy)-railRadius;
    float leftRail = length(rightD.xy)-railRadius;
    float bottomRail = length(bottomD.xy)-railRadius;

    float rails = min(leftRail, rightRail);
   	rails = min(rails, bottomRail);

    // Boxes
    vec3 bottomBoxD = RailPath(q, vec2(0.0, 0.15));
    vec3 leftBoxD = RailPath(q, vec2(-0.55*RAIL_WIDTH, 0.5*(RAIL_HEIGHT)));
    vec3 rightBoxD = RailPath(q, vec2(0.55*RAIL_WIDTH, 0.5*(RAIL_HEIGHT)));

    float roll = RailAngle(q.z);
    pR(bottomBoxD.xy, -roll);
    pR(leftBoxD.xy, -roll);
    pR(rightBoxD.xy, -roll);

    float rep = 3.5;
    pMod1(bottomBoxD.z, rep);
    pMod1(leftBoxD.z, rep);
    pMod1(rightBoxD.z, rep);

    float thickness = 0.025;
    float bottomBox = fBoxCheap(bottomBoxD, vec3(RAIL_WIDTH*0.55, 0.1, thickness));
    float leftBox = fBoxCheap(leftBoxD, vec3(thickness, 0.25, thickness));
    float rightBox = fBoxCheap(rightBoxD, vec3(thickness, 0.25, thickness));

    float boxes = bottomBox;
    boxes = min(boxes, leftBox);
    boxes = min(boxes, rightBox);

    Hit dRails = Hit(
        fOpUnionRound(rails, boxes, 0.1),
        MAT_RAILS
    );

    return dRails;
}
Hit Tube(vec3 p){
    vec3 tubeD = RailPath(vec3(-p.x, -p.y, p.z), vec2(0.0, 0.0));
    float liTime = iTime-0.8;
    float spacing = 1400.;
    float radius = 12.0;
    if(liTime >12.5 && liTime <16.){

    radius-=(liTime-12.5)*4.1;

    }
    if(liTime >16.){
    radius=1.0;
    radius+=clamp(-1.,10.,(liTime-16.)*4.0);
    NUM_BOUNCES = 2;
    }
    float cylinder = radius-length(tubeD.xy);
    float cube = radius-(abs(tubeD.x-.9)+abs(tubeD.y+.4));


    float tube = mix(
        cube,
        cube,
        saturate(smoothstep(0.49,0.51, fract(tubeD.z/spacing)))
    );


    Hit dTube = Hit(
        tube,
        MAT_TUBE
    );

    return dTube;
}

Hit GetDist(vec3 p){
   	Hit rails = Rails(p);
    Hit tube = Tube(p);

    return OpUnionHit(tube, tube);
}

Hit RayMarch(vec3 ro, vec3 rd, int bounce){
	float dO = 0.2;
    Hit hit;

    int steps = MAX_STEPS;

    if(bounce > 0){
        steps /= bounce*4;
    }

    for(int i = 0; i < steps; i++){
        vec3 p = dO*rd+ro;
        hit = GetDist(p);

        dO += hit.d;

        if(hit.d < SURFACE_DIST || dO > MAX_DIST){
            break;
        }
    }
    return Hit(dO, hit.ID);
}


Material GetMaterial(in vec3 p, in vec3 n, in Hit hit){
    Material mat;

    if(hit.ID == MAT_RAILS){


        mat.albedo = vec3(1.0, 0., 0.3);
        mat.metallic = vec3(0.0);
        mat.roughness = 1.0;
    }else if(hit.ID == MAT_TUBE){


        float f = smoothstep(0.0, 0.09+hit.d*hit.d*0.0003, abs(fract(p.z*0.25)-0.5));
        float angle = atan(p.y, p.x)/TAU + 0.5;
        f *= smoothstep(0.0, 0.06+hit.d*hit.d*0.0002, abs(fract(angle*20.)-0.5));
        mat.albedo = mix(
            vec3(0.5, 0.2, 0.7),
            vec3(1.0, 0.2, 1.0)*7.,
            1. - saturate(f)
        );
        mat.metallic = vec3(1.0);
        mat.roughness = 0.1;
    }else{
        mat.albedo = vec3(0.0, 0.0, 0.5);
        mat.metallic = vec3(0.0);
        mat.roughness = 1.0;
    }

    return mat;
}

vec3 GetNormal(vec3 pos){
 	vec2 e = vec2(1.0,-1.0)*0.5773*0.05;
    return normalize( e.xyy*GetDist( pos + e.xyy ).d + 
					  e.yyx*GetDist( pos + e.yyx ).d + 
					  e.yxy*GetDist( pos + e.yxy ).d + 
					  e.xxx*GetDist( pos + e.xxx ).d );
}

float CalcAO(vec3 ro, vec3 rd){
    float k = 1.0;
    float occ = 0.0;
    for(float i = 0.0; i < NUM_AO_STEPS; ++i){
        float len = 0.15 * i + 0.15;
        float dist = GetDist(rd * len + ro).d;
        occ += k * (len - dist);
        k *= 0.5;
    }
    return saturate(1.0-occ);
}

vec4 GetColor(vec3 ro, vec3 rd){
    int bounce = 0;
    float depth = 0.;

    vec3 res = vec3(0.0);
    vec3 carry = vec3(1.0);

    for(int bounce = 0; bounce <= NUM_BOUNCES; ++bounce){
        Hit hit = RayMarch(ro, rd, bounce);
        if(bounce == 0)depth = hit.d;

        depth = hit.d;

        if(hit.d >= MAX_DIST){
            return vec4(SKY_COLOR, depth);
        }

        vec3 p = rd * hit.d + ro;
        vec3 n = GetNormal(p);
        vec3 v = normalize(ro-p);

        Material mat = GetMaterial(p, n, hit);

        vec3 col = mat.albedo;

        float ao = CalcAO(p, n);

        col *= (1. / pow(length(p-ro), 1.5)) *
            pow(saturate(dot(n, normalize(v))), 2.0);

        col += 0.002;

        col *= ao*ao;

        res += col * carry;

        carry = mat.albedo * carry * (1.0 - mat.roughness);

        if(length(carry) < 0.05){break;}

        // bounce ray
        rd = rd - 2.0*dot(rd, n)*n;
        ro = p + rd*0.001;
    }

    return vec4(res, depth);
}
